int rock_ridge_continuation(struct rock_state *rs) {
  if (!rs || rs->offset < 0 || rs->size < 0 || rs->offset + rs->size > rs->block_size) {
    return -1;
  }

  void *buffer = malloc(rs->size);
  if (!buffer) {
    return -1;
  }

  if (read_extent(rs->extent, buffer, rs->offset, rs->size) != rs->size) {
    free(buffer);
    return -1;
  }

  rs->buffer = buffer;
  rs->remaining = rs->size;
  rs->offset += rs->size;

  return 0;
}

int rock_ridge_cont(struct rock_state *rs) {
    if (rs->offset + rs->size > rs->block_size) {
        return -EINVAL;
    }

    void *buffer = malloc(rs->size);
    if (!buffer) {
        return -ENOMEM;
    }

    int result = read_extent(rs->extent, buffer, rs->offset, rs->size);
    if (result < 0) {
        free(buffer);
        return result;
    }

    rs->buffer = buffer;
    rs->remaining = rs->size;
    return 0;
}

int rock_ridge_continue(struct rock_state *rs) {
    if (rs->offset >= rs->block_size || rs->size > rs->block_size - rs->offset) {
        return -EINVAL;
    }

    if (rs->buffer) {
        free(rs->buffer);
        rs->buffer = NULL;
    }

    rs->buffer = malloc(rs->size);
    if (!rs->buffer) {
        return -ENOMEM;
    }

    if (read_extent(rs->extent, rs->buffer, rs->offset, rs->size) < 0) {
        free(rs->buffer);
        rs->buffer = NULL;
        return -EIO;
    }

    rs->offset += rs->size;
    return 0;
}

int rock_continue_scan(struct rock_state *rs) {
    if (!rs || rs->offset >= rs->extent->data_size || rs->offset + rs->size > rs->extent->data_size) {
        return -EINVAL;
    }

    void *buffer = malloc(rs->size);
    if (!buffer) {
        return -ENOMEM;
    }

    if (read_extent_data(rs->extent, buffer, rs->offset, rs->size) < 0) {
        free(buffer);
        return -EIO;
    }

    rs->buffer = buffer;
    rs->offset += rs->size;
    rs->size = 0;
    return 0;
}

int rock_ridge_cont_entry(struct rock_state *rs) {
  if (rs->offset + rs->size > rs->block_size) {
    return -1;  // Invalid offset/size beyond block size
  }

  void *buffer = malloc(rs->size);
  if (!buffer) {
    return -2;  // Memory allocation failed
  }

  if (read_extent(rs->extent, buffer, rs->offset, rs->size) < 0) {
    free(buffer);
    return -3;  // Read from extent failed
  }

  rs->buffer = buffer;
  rs->offset += rs->size;

  return 0;
}
